// DOM text stays at screen resolution instead of being resampled with the world camera.
export function labelPoint(camera,point){return{x:Math.round((point.x-camera.scrollX-camera.width*.5)*camera.zoom+camera.width*.5+(camera.x||0)),y:Math.round((point.y-camera.scrollY-camera.height*.5)*camera.zoom+camera.height*.5+(camera.y||0))};}
export function placeLabels(candidates,width,height){const occupied=[],result=[];for(const c of [...candidates].sort((a,b)=>b.priority-a.priority||a.distance-b.distance)){const w=Math.min(230,Math.max(40,c.text.length*6.5+16)),h=23,x=Math.max(w/2+6,Math.min(width-w/2-6,c.x)),y=c.y;const box={x:x-w/2,y:y-h,w,h};if(y<95||y>height-120||c.x<-30||c.x>width+30||occupied.some(b=>box.x<b.x+b.w+5&&box.x+box.w+5>b.x&&box.y<b.y+b.h+5&&box.y+box.h+5>b.y))continue;occupied.push(box);result.push({...c,x,y});if(result.length>=8)break;}return result;}
export class WorldLabels{
 constructor(parent,project){this.project=project;this.nodes=new Map();this.layer=parent.ownerDocument.createElement('div');this.layer.className='world-labels';this.layer.setAttribute('aria-hidden','true');parent.append(this.layer);}
 update(s,h,camera){const project=this.project,candidates=[],add=(id,text,point,distance,priority,kind)=>{const p=labelPoint(camera,project(point.x,point.y));candidates.push({id,text,...p,distance,priority,kind});};
 for(const e of [...Object.values(s.players),...s.enemies]){if(e.dead||e.id===h.id)continue;const distance=Math.hypot(e.x-h.x,e.y-h.y);if(distance>(e.id===h.target?14:4.5))continue;const world=project(e.x,e.y),point=labelPoint(camera,{x:world.x,y:world.y-(e.boss?145:85)});candidates.push({id:e.id,text:e.classId?e.name:(e.elite?'✦ ':'')+e.name+' · '+e.level,...point,distance,priority:e.id===h.target?100:e.boss?80:40,kind:e.classId?'ally':'enemy'});}
 for(const o of s.labelObjects||[]){const distance=Math.hypot(o.x-h.x,o.y-h.y);if(distance>(o.kind==='npc'?7:3.5)||o.kind==='trap'||o.kind==='relic'&&s.flags.seals.includes(o.id)||o.id==='inner-door'&&s.flags.switch||o.kind==='ward'&&s.flags.wardBroken)continue;add('object:'+o.id,o.name,{x:o.x+.5,y:o.y+.5},distance,o.kind==='npc'?70:30,'object');}
 const visible=placeLabels(candidates,camera.width,camera.height),ids=new Set(visible.map(c=>c.id));for(const c of visible){let el=this.nodes.get(c.id);if(!el){el=this.layer.ownerDocument.createElement('span');el.className='world-label';this.layer.append(el);this.nodes.set(c.id,el);}el.textContent=c.text;el.dataset.kind=c.kind;el.style.left=c.x+'px';el.style.top=c.y+'px';el.hidden=false;}for(const [id,el]of this.nodes)if(!ids.has(id))el.hidden=true;
 }
 destroy(){this.layer.remove();this.nodes.clear();}
}
